INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT159-S1-Q17$batch05$, 159, 1, 17, $batch05$Necessary Assumption$batch05$, $batch05$Essayist: It would be wrong to defend current testing procedures for new medications simply by appealing to the fact that test subjects are volunteers who are both apprised of and compensated for the risks involved. For while it is not wrong to pay people to do something if they are freely choosing to do it, the same cannot be said if the choice is made under duress.$batch05$, $batch05$Which one of the following is an assumption required by the essayist’s argument?$batch05$, $batch05$A$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$Possessing information about the possible consequences of the choices one makes does not ensure that one’s choices are free.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$No transaction can be justified merely on the grounds that those participating in the transaction do so voluntarily.$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$Anyone who acts without complete freedom is acting under some form of externally imposed duress.$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$There is nothing wrong with accepting money for putting oneself at risk.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$People should be permitted to perform any action so long as that action is freely chosen.$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$It is wrong to defend current drug testing *simply* because the subjects are informed volunteers who are paid.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Paying people is fine when they choose freely, but not when the choice is made under duress.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The defense rests on two facts: the subjects are informed, and they volunteer. The essayist answers by bringing up duress. But duress only matters if being informed is not enough to make a choice free. If knowing the risks guaranteed a free choice, the defense would hold. So the essayist has to assume information and freedom can come apart.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: knowing the risks does not guarantee the choice is free.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Negate it: "being informed about the consequences *does* guarantee the choice is free." Then informed volunteers are choosing freely, paying them is fine, and the defense the essayist rejects is actually sound.$batch05$), ($batch05$B$batch05$, $batch05$"No transaction" can ever be justified by voluntariness alone? The essayist does not go that far. They say voluntariness plus payment is not enough *here* because duress is possible.$batch05$), ($batch05$C$batch05$, $batch05$Linking every limit on freedom to outside duress is a broad claim the argument never needs.$batch05$), ($batch05$D$batch05$, $batch05$The essayist is not saying risk-for-money is wrong in itself, only that it is wrong under duress.$batch05$), ($batch05$E$batch05$, $batch05$"Any action" freely chosen should be allowed is a sweeping principle, and it points the wrong way for this argument.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT159-S1-Q17$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
